#!/usr/bin/env python3
"""Actual PostgreSQL allocation component checks; no provider or transport qualification."""
import importlib.util,json,subprocess,uuid
from pathlib import Path
ROOT=Path(__file__).resolve().parents[4]
s=importlib.util.spec_from_file_location('allocation_resources',ROOT/'tests/hyperfide/cases/tasks/5_4.py');m=importlib.util.module_from_spec(s);s.loader.exec_module(m)
uid=lambda:str(uuid.uuid4())
def main():
 f=m.ResourceFixture();i=f.ids;results=[]
 try:
  session,slot,credential,obs,reason,decision=[uid() for _ in range(6)];pin=m.sha(b'allocation component fixture facts')
  f.sql("INSERT INTO hyperfide.worker_slots(organisation_id,id,sandbox_id,slot_key,boot_generation,capacity_kind,state) VALUES($1,$2,$3,'allocation-preparation',1,'PREPARATION','READY')",[i['organisation'],slot,i['sandbox']])
  f.sql("INSERT INTO hyperfide.agent_sessions(organisation_id,run_id,id,role,parent_session_id,connector,account_key,native_session_id,slot_id,sandbox_id,sandbox_boot_generation) VALUES($1,$2,$3,'WORKER',$4,'fixture','fixture','allocation-component',$5,$6,1)",[i['organisation'],i['run'],session,i['manager'],slot,i['sandbox']])
  f.sql("INSERT INTO hyperfide.identity_principals(credential_id,organisation_id,run_id,actor_id,role,public_key_b64,deployment_epoch,allowed_actions,expires_at,sandbox_id,boot_id,boot_generation) VALUES($1,$2,$3,$4,'RUNNER',$5,$6,ARRAY['system.describe'],clock_timestamp()+interval '1 hour',$7,$8,1)",[credential,i['organisation'],i['run'],session,f.keys['operator']['public_key_b64'],i['epoch'],i['sandbox'],i['boot']])
  f.sql("INSERT INTO hyperfide.identity_runner_status(credential_id,preparation_digest,inventory) VALUES($1,$2,'[]')",[credential,f.preparation])
  f.sql("INSERT INTO hyperfide.runner_registry(organisation_id,run_id,session_id,credential_id,sandbox_id,boot_generation,boot_id,slot_id,repository_id,state_dir,runner_binary,workspace_path,home_path,tmp_path,runner_binary_digest,boot_preparation_digest,preparation_digest,preparation_recipes,slot_generation,uid,gid,observation_digest,state) VALUES($1,$2,$3,$4,$5,1,$6,$7,$8,'/component/state','/component/native','/component/source','/component/home','/component/tmp',$9,$10,$10,'{}',1,62041,62041,$9,'PREPARING')",[i['organisation'],i['run'],session,credential,i['sandbox'],i['boot'],slot,i['repository'],pin,f.preparation])
  budget={'task_ids':[i['task_a']],'provider_ids':['fixture'],'profile_ids':[i['profile']]}
  f.sql("INSERT INTO hyperfide.fleet_delegations(organisation_id,run_id,package_id,manager_session_id,manager_generation,leader_generation,budget,decision_id) VALUES($1,$2,$3,$4,2,1,$5,$6)",[i['organisation'],i['run'],i['package'],i['manager'],json.dumps(budget),decision])
  f.sql("INSERT INTO hyperfide.fleet_observations(organisation_id,run_id,id,actor_id,cohort_generation,context_digest,body) VALUES($1,$2,$3,$4,1,$5,'{}')",[i['organisation'],i['run'],obs,i['manager'],pin])
  f.sql("INSERT INTO hyperfide.fleet_reasoning(organisation_id,run_id,id,actor_id,request_digest,observation_id,state) VALUES($1,$2,$3,$4,$5,$6,'COMPLETED')",[i['organisation'],i['run'],reason,i['manager'],pin,obs])
  f.sql("INSERT INTO hyperfide.fleet_decisions(organisation_id,run_id,id,operation_id,actor_id,action,context_digest,payload_digest,reasoning_id,body) VALUES($1,$2,$3,$4,$5,'PROVISION_SANDBOX',$6,$6,$7,'{}')",[i['organisation'],i['run'],decision,uid(),i['manager'],pin,reason])
  f.sql("INSERT INTO hyperfide.fleet_effect_receipts(organisation_id,run_id,operation_id,decision_id,payload_digest,result) VALUES($1,$2,$3,$4,$5,$6)",[i['organisation'],i['run'],uid(),decision,pin,json.dumps({'delegation_id':i['package'],'sandbox_id':i['sandbox']})])
  request=dict(request_id=uid(),task_id=i['task_a'],package_id=i['package'],manager_session_id=i['manager'],manager_generation='2',leader_generation='1',authority_epoch=i['epoch'],session_id=session,slot_id=slot,slot_generation='1',sandbox_id=i['sandbox'],boot_id=i['boot'],boot_generation='1',deadline_ms=300000)
  script="""import fs from 'node:fs';import {createResourceContainer} from './core/control-plane/dist/storage/runtime.js';import {authenticatedInvocation} from './core/control-plane/dist/transport/protocol.js';import {writeSemanticDisposition} from './core/control-plane/dist/storage/dispositions.js';import {allocateFleetJob} from './core/control-plane/dist/preparation/fleet_job_allocation.js';const d=JSON.parse(fs.readFileSync(0,'utf8')),r=createResourceContainer({role:'control',env:process.env,signal:new AbortController().signal});const guard=async tx=>{const v=(await tx.query("SELECT r.authority_epoch FROM hyperfide.runs r JOIN hyperfide.identity_principals p ON p.organisation_id=r.organisation_id AND p.run_id=r.id WHERE r.organisation_id=$1 AND r.id=$2 AND p.credential_id=$3 AND p.actor_id=$4 AND p.role=$5 AND p.state='ACTIVE' AND p.expires_at>clock_timestamp() AND p.deployment_epoch=r.authority_epoch",[d.org,d.run,d.credential,d.actor,d.role])).rows[0];if(v?.authority_epoch!==d.request.authority_epoch)throw Error('Fixture primary identity or authority changed');};const i=authenticatedInvocation({principal:{credential_id:d.credential,actor_id:d.actor,organisation_id:d.org,run_id:d.run,role:d.role,deployment_epoch:d.request.authority_epoch},signal:new AbortController().signal,guard});try{const result=await r.gateway.withPrimaryTransaction({timeoutMs:20000,maxRetries:2,guard:async tx=>{await writeSemanticDisposition(tx,{organisation_id:d.org,run_id:d.run});await guard(tx);}},tx=>allocateFleetJob(tx,i,d.request,d.purpose));console.log(JSON.stringify({result}));}catch(e){console.log(JSON.stringify({error:e.code??'ERROR',message:e.message}));}finally{await r.close();}"""
  def call(req,role='OPERATOR',purpose='PREPARATION',credential_id=None):
   p=subprocess.run(['node','--input-type=module','-e',script],input=json.dumps({'org':i['organisation'],'run':i['run'],'credential':credential if role=='RUNNER' else credential_id or i['operator'],'actor':session if role=='RUNNER' else i['operator'],'role':role,'request':req,'purpose':purpose}),cwd=ROOT,env=f.env,text=True,capture_output=True,timeout=30);assert p.returncode==0,p.stderr;return json.loads(p.stdout)
  before=f.counts();bad=call(request,role='RUNNER');assert bad['error']=='FLEET_JOB_ROLE',bad;assert f.counts()==before;results.append('unauthorized role leaves real quota unchanged')
  bad=call(dict(request,manager_session_id=i['leader']));assert 'error' in bad,bad;assert f.counts()==before;results.append('Primary cannot proxy a delegated package manager')
  bad=call(dict(request,boot_id=uid()));assert bad['error']=='FLEET_JOB_RUNNER',bad;assert f.counts()==before;results.append('stale selected boot rejected atomically')
  first=call(request);assert 'result' in first,first;allocation=first['result']['allocation'];assert allocation['job_kind']=='PREPARATION' and allocation['slot_id']==slot;results.append('accepted task creates actual purpose reservation and executor allocation')
  after=f.counts();replacement=uid();f.sql("INSERT INTO hyperfide.identity_principals(credential_id,organisation_id,run_id,actor_id,role,public_key_b64,deployment_epoch,allowed_actions,expires_at) VALUES($1,$2,$3,$4,'OPERATOR',$5,$6,ARRAY['system.describe'],clock_timestamp()+interval '1 hour')",[replacement,i['organisation'],i['run'],i['operator'],f.keys['operator']['public_key_b64'],i['epoch']]);replay=call(request,credential_id=replacement);assert replay==first,replay;assert f.counts()==after;results.append('credential rotation replays same logical actor allocation without quota duplication')
  bad=call(dict(request,deadline_ms=299999));assert bad['error']=='IDEMPOTENCY_CONFLICT',bad;assert f.counts()==after;results.append('changed immutable request rejected without reallocation')
  print(json.dumps({'status':'PASS','assertions':results,'scope':'trusted lower component on actual PostgreSQL','signed_public_api':'UNRUN','provider':'UNRUN'}))
 finally:f.close()
if __name__=='__main__':main()
